    dy = 0 if ty == sy else (1 if ty > sy else -1)

    cand = []
    # Try the most direct diagonal/axis steps first, then alternatives.
    for mx in (dx, 0, -dx):
        for my in (dy, 0, -dy):
            if (mx, my) == (0, 0):
                continue
            cand.append((mx, my))
    cand.append((dx, dy))
    cand.append((dx, 0))
    cand.append((0, dy))
    cand.append((0, 0))

    seen = set()
    for mx, my in cand:
        if (mx, my) in seen:
            continue
        seen.add((mx, my))
        nx, ny = sx + mx, sy + my
        if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in obstacles:
