        if 0 <= x < w and 0 <= y < h and (x, y) not in obstacles:
            resources.append((x, y))
    if not resources:
        return [0, 0]

    def bfs(start):
        inf = 10**9
        dist = [[inf] * h for _ in range(w)]
        if start in obstacles:
            return dist
        sx0, sy0 = start
        dist[sx0][sy0] = 0
        q = [(sx0, sy0)]
        head = 0
        while head < len(q):
            x, y = q[head]
            head += 1
            nd = dist[x][y] + 1
            for dx in (-1, 0, 1):
